window.DELTA_PAGES=[{"id":"ep01-p01","number":1,"title":"Sur la lande","image":"images/P01-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Maelrun était sur la lande depuis l’aube.","Depuis une quinzaine de jours, les bêtes avaient quitté les bergeries du village. Elles cherchaient les premières herbes tendres et poussaient plus loin chaque fois qu’un passage s’ouvrait. Il avait passé la matinée à les rappeler, à examiner celles qui boitaient ou restaient en arrière, puis à les réunir dans un creux où elles pouvaient brouter à l’abri du vent.","À présent, il les regardait avancer lentement, les têtes baissées. Il choisit une pierre sur le haut de la pente, prit un caillou dans sa poche et dégagea sa fronde. Une rafale courba l’herbe. Il la laissa passer, lança et vit la terre sauter sous sa cible. Au second essai, le caillou frappa la pierre avec un bruit sec."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[{"label":"P01 · 01 — Version antérieure","filename":"Delta-Episode-1-P01-V2-reference.png","image":"images/P01-01-ancienne.png"}],"currentLabel":"P01 — Version disponible","sourceLines":[3,7],"planOrigin":1,"plan":"Maelrun observe le troupeau regroupé, choisit une cible, attend la rafale, manque puis touche la pierre.","staging":"Distinguer le creux abrité et la pente de tir ; garder les moutons hors de l'axe."},{"id":"ep01-p02","number":2,"title":"Les garçons rejoignent Maelrun","image":"images/P02-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Depuis le bois derrière le village, les garçons remontaient vers la lande en relevant au passage les quelques pièges posés les jours précédents. Carnoc marchait devant, suivi de Belenmar, qui portait la prise du matin à la ceinture, tandis qu’Orvenn fermait la marche. En débouchant sur la lande, ils aperçurent Maelrun qui se détachait plus haut sur la pente. Un nouveau claquement leur parvint.","— Tu vas finir par la casser, lança Carnoc.","À quelques pas de Maelrun, il se baissa et ramassa une pierre."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P02 — Version disponible","sourceLines":[9,15],"planOrigin":2,"plan":"Carnoc, Belenmar et Orvenn rejoignent Maelrun ; Carnoc prend un caillou et emprunte la fronde.","staging":"Continuité de l’arrivée et lièvre à la ceinture de Belenmar ; planche validée."},{"id":"ep01-p03","number":3,"title":"Le tir de Carnoc","image":"images/P03-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Maelrun se retourna. Carnoc s’avança vers lui et tendit la main vers la fronde. Maelrun la lui donna. Le garçon plaça la pierre dans la poche, referma les doigts sur les deux brins et prit son appui. Il fit tourner la fronde une première fois, puis accéléra le mouvement avant de lâcher. Son projectile disparut dans l’herbe, à côté.","— Il y avait du vent.","Orvenn regarda les touffes qui pliaient autour d’eux. Belenmar sourit. Carnoc rendit la fronde, puis les garçons s’installèrent sur le talus.","— Demain, on pourrait sortir, dit Carnoc.","— Demain, on est à la forge, répondit Belenmar."],"notes":"Deux répliques « demain… » ont été déplacées depuis P04 en case 6. La frontière de texte proposée reste à ajuster aux bulles de la version retenue.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P03 — Version disponible","sourceLines":[17,21],"planOrigin":3,"plan":"Carnoc rejoint Maelrun, emprunte la fronde, manque son tir et invoque le vent.","staging":"Geste maladroit, regard d'Orvenn sur l'herbe, sourire de Belenmar."},{"id":"ep01-p04","number":4,"title":"Un projet de barque","image":"images/P04-selection.jpg","hasImage":true,"status":"Montage retenu","paragraphs":["Ils restèrent un moment à parler des beaux jours. Les chemins séchaient enfin ; Carnoc voulait reprendre une barque et longer la côte jusqu’à un endroit où ils pourraient passer la nuit. Belenmar lui rappela qu’ils étaient attendus à la forge le lendemain. Leur père avait des ferrures à reprendre, et Carnoc devrait tenir le soufflet.","— On peut partir après, dit-il.","— Avec quelle barque ? demanda Orvenn.","Carnoc lui en proposa une. Orvenn la connaissait. Elle prenait l’eau et l’état de ses bordages ne lui inspirait aucune confiance. Carnoc comptait justement sur lui pour cela."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Dernières consignes","quote":"Conserver les positions assises et l’échange léger en P04 ; le mouvement et les répliques d’Orvenn passent en P05.","state":"Montage retenu","pending":false}],"history":[{"label":"P04 · 01 — Version antérieure","filename":"Delta-Episode-1-P04-reference.png","image":"images/P04-01-ancienne.png"}],"currentLabel":"P04 — Version disponible","sourceLines":[23,29],"planOrigin":4,"plan":"Projet de promenade en barque ; forge, soufflet, réparations et atelier rappellent les obligations.","staging":"Distribution des quatre garçons dans le talus ; place des dialogues à fixer."},{"id":"ep01-p05","number":5,"title":"La Vieille Lune","image":"images/P05-selection.jpg","hasImage":true,"status":"Montage retenu","paragraphs":["Orvenn se redressa sur un coude et commença à énumérer ce qu’il faudrait reprendre. Tout en parlant, il ramena un genou sous lui et se releva. Lorsqu’il répondit enfin à Carnoc, il se tenait debout devant lui.","— Mon père m’attend aussi à l’atelier.","Il croisa un bras sur sa poitrine et porta l’autre main à son visage. Il resta ainsi un instant, cherchant ses mots.","— Je suis allé voir la Vieille Lune. Je pensais terminer les travaux pour qu’on puisse s’en servir.","Belenmar riait déjà, assis sur la partie sèche du talus.","Carnoc arracha une tige sèche. Il réfléchit un instant, puis remit leur départ à plus tard dans la semaine. Maelrun l’écoutait en surveillant les bêtes. Une brebis avait gagné le bord du creux ; elle s’arrêta pour brouter et les autres restèrent où elles étaient."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Dernières consignes","quote":"En P05 / case 4, Carnoc demande : « À quoi penses-tu ? »","state":"Montage retenu","pending":false}],"history":[{"label":"P05 · 01 — Version antérieure","filename":"Delta-Episode-1-P05-reference.png","image":"images/P05-01-ancienne.png"}],"currentLabel":"P05 — Version disponible","sourceLines":[31,41],"planOrigin":5,"plan":"Suite de la discussion sur la barque ; plaisanterie du seau, puis les garçons se lèvent.","staging":"Maintenir les positions jusqu’au lever ; planche validée."},{"id":"ep01-p06","number":6,"title":"La rencontre des enfants","image":"images/P06-selection.jpg","hasImage":true,"status":"Composition retenue","paragraphs":["Le soleil commençait à leur réchauffer le dos quand Belenmar se releva. Carnoc reprit les pièges, tandis que Maelrun rangeait sa fronde et ramassait son bâton. Il regarda encore le troupeau avant de suivre les garçons vers les bois.","Le chemin descendait entre les ajoncs. À l’entrée du couvert, l’air devint plus frais et leurs pas s’enfoncèrent dans une terre encore molle. Carnoc parlait toujours de sa barque lorsqu’il aperçut les enfants.","— Brieg !","Il avança vers lui, mais le garçon resta entre les arbres. Il tenait Elen par la main ; Ronan marchait presque contre son autre côté. Derrière eux, les plus jeunes se serraient autour d’Elvenn.","Maelrun ralentit. Le vieux druide regardait au-delà du chemin, puis revenait vers les enfants pour vérifier qu’ils le suivaient. Son bâton demeurait levé dans sa main.","— Qu’est-ce que tu as vu ? demanda Maelrun."],"notes":"Les dialogues ajoutés sur la Vieille Lune sont signalés dans les annotations ; ils ne remplacent pas automatiquement le texte source.","annotations":[{"case":"Dernières consignes","quote":"Six cases 1:2:2:1. Dialogues en 2/3/4, « Brieg ! » en 4. Main gauche de Maelrun sur l’épaule de Carnoc en 5 ; Maelrun au contact d’Elvenn en 6.","state":"Composition retenue","pending":false}],"history":[{"label":"P06 · 01 — Version antérieure","filename":"Delta-Episode-1-P06-reference.png","image":"images/P06-01-ancienne.png"}],"currentLabel":"P06 — Version disponible","sourceLines":[43,53],"planOrigin":6,"plan":"Dernier regard au troupeau, descente, rencontre d’Elvenn et des six enfants. Maelrun perçoit l’inquiétude, retient l’élan de Carnoc et s’avance vers Elvenn.","staging":"Brieg reste à peine plus grand que le plus grand des autres enfants ; Elvenn conserve sa stature adulte ; planche validée."},{"id":"ep01-p07","number":7,"title":"La fumée d’Arloc","image":"images/P07-selection.jpg","hasImage":true,"status":"Conformité à vérifier","paragraphs":["Elvenn désigna une ouverture entre les branches. Les garçons durent avancer jusqu’à lui pour apercevoir, au-dessus des cimes, une fumée sombre que le vent étirait vers les terres.","— Cela vient d’Arloc, dit-il.","Orvenn se déplaça pour mieux voir. Une branche lui cachait la naissance de la fumée ; il la repoussa, mais les maisons restaient derrière le bois. Carnoc avait cessé de parler.","Elvenn ramena les enfants auprès de lui. Il allait les éloigner du chemin. Les garçons chercheraient à voir ce qui se passait, en restant sous le couvert. Il retint Maelrun un instant par la manche.","— Regardez les passages avant de les prendre.","Maelrun acquiesça. Brieg les suivit des yeux pendant qu’ils s’éloignaient, puis Elvenn l’appela doucement et il entraîna Elen derrière les autres."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Dernières consignes","quote":"Reprendre les personnages de référence. Dernière case : Carnoc, Belenmar, Orvenn, Maelrun en retrait tourné vers Elvenn. En 5, bras et bâton derrière Elvenn sont masqués.","state":"Conformité à vérifier","pending":true}],"history":[],"currentLabel":"P07 — Version disponible","sourceLines":[55,65],"planOrigin":7,"plan":"Elvenn montre la fumée d’Arloc, retient Maelrun par la manche et donne sa consigne ; les groupes se séparent.","staging":"Déplacement nécessaire pour voir ; six enfants maintenus à couvert ; raccord vers Arua ; planche validée."},{"id":"ep01-p08","number":8,"title":"Arua découvre la baie","image":"images/P08-selection.jpg","hasImage":true,"status":"Provisoire · cases 1 et 2 à refaire","paragraphs":["Arua avait quitté Arloc plus tôt dans la matinée pour prendre des nouvelles d’un village du sud. Elle avait suivi la ria, remonté jusqu’au passage de la rivière et gagné l’autre rive. Sous les arbres, son cheval avançait avec précaution dans les parties encore molles du chemin.","La baie s’ouvrit peu à peu devant elle. Entre les troncs, elle aperçut un navire au mouillage. Elle ralentit pour le regarder. À chaque pas, une autre partie de la rive se découvrait ; une fumée apparut, puis une seconde, plus basse. Elle poussa jusqu’à un endroit où les branches s’espaçaient.","Arloc brûlait de l’autre côté de l’eau.","Elle retint le cheval et chercha à distinguer les maisons. Une lueur grandit entre deux toits. Il lui fallut un moment pour détacher les yeux du village et regarder les accès autour d’elle."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Dernières consignes","quote":"Les cases 1 et 2 seront à refaire. Conserver la progression de la découverte, l’arbre repère, la marée à mi-hauteur et la barque au loin.","state":"Provisoire · cases 1 et 2 à refaire","pending":true}],"history":[{"label":"P08 · 01 — Version antérieure","filename":"Delta-Episode-1-P08-reference.png","image":"images/P08-01-ancienne.png"}],"currentLabel":"P08 — Version disponible","sourceLines":[69,75],"planOrigin":8,"plan":"Arua découvre le navire et l’incendie","staging":"Eau, vent côtier, pas du cheval ; raccord sur la fumée."},{"id":"ep01-p09","number":9,"title":"Le débarquement","image":"images/P09-selection.jpg","hasImage":true,"status":"Cadrages validés · à harmoniser","paragraphs":["Sur la rive sud, Arua vit une barque traverser la baie. Elle reconnut sa forme et avança hors du couvert. Des habitants avaient peut-être réussi à partir. Elle chercha leurs visages tandis que l’embarcation approchait de la rive.","Le premier homme se retourna. Elle le regarda, puis le second. Un troisième, plus âgé, leur cria quelque chose depuis l’arrière. Arua ramena le cheval sous les arbres. La barque venait d’Arloc ; les hommes lui étaient inconnus.","Elle tourna sa monture vers le chemin du retour. Devant elle, les bois cachaient les passages qui rejoignaient les terres de Morna et les abords du village ancien. Elle fit quelques pas, puis entendit la coque toucher la vase.","Deux hommes se préparaient à descendre. Le plus jeune posa un pied, s’enfonça et se rattrapa au bord. L’autre attendit qu’il ait avancé avant de le suivre. Pour gagner le couvert, ils devaient traverser cette bande molle, puis atteindre le sable plus ferme au pied des arbres.","Arua revint en retrait de la grève. Elle posa la main sur l’encolure du cheval et attendit. Le jeune avançait en arrachant ses pieds à la vase ; son compagnon restait derrière. L’ancien maintenait la barque et surveillait leur progression.","Une fois sur le sable, le jeune se laissa tomber assis. L’homme resté à bord lui cria de se relever et lui montra l’amarre. Il obéit avec lenteur. Son compagnon atteignait seulement la bordure de la vase."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Dernières consignes","quote":"Les plans sont bons ; il s’agira d’harmoniser. Conserver les cadrages, les positions et les distances.","state":"Cadrages validés · à harmoniser","pending":true}],"history":[{"label":"P09 · 01 — Version antérieure","filename":"Delta-Episode-1-P09-reference.png","image":"images/P09-01-ancienne.png"}],"currentLabel":"P09 — Version disponible","sourceLines":[145,155],"planOrigin":21,"plan":"Approche de la barque, identification des inconnus, échouage et débarquement dans la vase ; Arua reste à couvert.","staging":"Faire lire son choix par ses déplacements et son regard."},{"id":"ep01-p10","number":10,"title":"L’assaut d’Arua","image":"images/P10-selection.jpg","hasImage":true,"status":"À recomposer","paragraphs":["Arua raccourcit les rênes. Le cheval prit de la vitesse sous les branches et déboucha sur la grève. Le jeune entendit les sabots et commença à se retourner. Elle orienta sa monture pour le prendre de côté ; le choc le jeta au sol et l’amarre lui échappa.","Le second leva le bras en reculant. Arua avait dégagé sa lame. Elle choisit un coup qui lui ferait abandonner la rive en lui laissant la force de repartir. L’homme cria et perdit l’équilibre. Elle poursuivit quelques foulées avant de ralentir et de se retourner.","L’ancien les rappelait depuis la barque. Le jeune essayait de se relever ; l’autre reculait vers l’eau en tenant son bras contre lui. Arua demeura un instant à portée de leurs regards, puis reprit le chemin sous les arbres.","Le retour lui parut long. Elle dut ramener le cheval au pas pour franchir les endroits où la terre se dérobait et surveiller les passages qui s’ouvraient sur les côtés. La fumée disparaissait derrière les versants, revenait au-dessus des branches. Lorsqu’elle put quitter la rive pour gagner la chaumière, elle se pencha un peu sur l’encolure et laissa sa monture allonger le pas."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Dernières consignes","quote":"Les dernières recompositions ont été rejetées : perspective, distances, direction sur le chemin et îles ajoutées. La référence antérieure est présentée ici en attente de reprise.","state":"À recomposer","pending":true}],"history":[{"label":"P10 · Essai 1 rejeté — après la référence","filename":"exec-fff00259-c69d-4a9e-9311-d437b8c343b4.png","image":"images/P10-essai-rejete-1.png"},{"label":"P10 · Essai 2 rejeté — après la référence","filename":"exec-5f90558a-5a30-4886-8d8f-f24d17d0d96d.png","image":"images/P10-essai-rejete-2.png"}],"currentLabel":"P10 — Référence antérieure conservée · à reprendre","sourceLines":[157,163],"planOrigin":22,"plan":"Charge d’Arua, chute du jeune, blessure au bras du second et vue de sortie après l’assaut. Le retour vers la chaumière figure dans le récit associé.","staging":"Axe de course, terrain praticable et position de la barque à vérifier."},{"id":"ep01-p11","number":11,"title":"Des voix dans le bois","image":"images/P11-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Sous le couvert, les quatre avaient poursuivi leur descente sans reprendre leur conversation. À un endroit où le chemin se resserrait, Belenmar leva la main. Une voix venait d’en bas. Ils quittèrent le passage et attendirent entre les fourrés.","Deux hommes montaient vers eux. Le premier portait une arme à la ceinture et regardait les ouvertures du bois en marchant. Le second, plus jeune, s’arrêta pour reprendre quelque chose qui glissait sur son épaule. Leurs vêtements et leurs voix étaient étrangers aux garçons.","Maelrun chercha Belenmar du regard. Les deux frères s’étaient tassés près du chemin. Orvenn avait sorti sa fronde et choisissait une pierre dans le sol humide. Maelrun en prit une dans sa poche. Il attendit que Carnoc soit dissimulé à côté de son frère, puis indiqua à Orvenn le plus jeune des deux hommes.","L’autre approchait. Maelrun pouvait maintenant entendre sa respiration entre ses paroles. Il leva légèrement la main."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P11 — Version disponible","sourceLines":[79,85],"planOrigin":9,"plan":"Retour aux garçons après leur progression sous couvert ; des voix les arrêtent, ils découvrent deux hommes et se répartissent.","staging":"Faire sentir le trajet accompli pendant la séquence d’Arua ; conserver un temps d’écoute et de repérage avant le contact."},{"id":"ep01-p12","number":12,"title":"Les tirs de fronde","image":"images/P12-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Orvenn fit tourner sa fronde. La lanière passa une seconde fois et l’homme leva la tête vers lui. Maelrun lança aussitôt. Son projectile atteignit l’homme, qui perdit l’appui de ses jambes et tomba sur le chemin. Presque en même temps, le jeune reçut celui d’Orvenn. Il recula contre le talus, encore debout, et porta la main à son arme."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P12 — Version disponible","sourceLines":[87,87],"planOrigin":10,"plan":"Orvenn amorce trop visiblement son geste ; Maelrun tire ; les deux impacts ont des effets différents.","staging":"Décomposer l'ordre des gestes sans confondre les cibles."},{"id":"ep01-p13","number":13,"title":"Maîtriser le jeune pirate","image":"images/P13-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Belenmar le heurta de côté. Carnoc se jeta sur lui avec son frère ; tous trois tombèrent dans les feuilles. Le jeune se débattit, un bras pris sous Belenmar, l’autre cherchant à repousser Carnoc. Maelrun arriva près d’eux et dégagea l’arme avant qu’une main puisse l’atteindre.","— Tiens-le, souffla Belenmar.","Carnoc pesait de tout son corps sur les épaules du garçon. À cette distance, il voyait le duvet sur sa joue et les yeux qui passaient de l’un à l’autre. Il pouvait avoir leur âge. Il essaya de parler ; Belenmar lui rabattit la bouche contre sa manche pendant qu’Orvenn cherchait de quoi lui attacher les mains.","Les liens rapportés avec les pièges étaient à portée. Carnoc en tira un sans lâcher sa prise. Ils durent s’y reprendre pour maintenir les poignets ensemble. Quand le jeune fut immobilisé et bâillonné, Maelrun retourna auprès de l’autre homme."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P13 — Version disponible","sourceLines":[89,95],"planOrigin":11,"plan":"Belenmar et Carnoc maîtrisent le plus jeune ; Maelrun écarte son arme.","staging":"Appuis et prises lisibles ; le visage du pirate révèle sa jeunesse."},{"id":"ep01-p14","number":14,"title":"Lier et dissimuler","image":"images/P14-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Il respirait. Orvenn s’agenouilla et posa la main devant sa bouche, puis ils le tirèrent hors du passage. Son poids les obligea à s’arrêter deux fois. Ils attachèrent aussi ses mains et le laissèrent sur le côté, auprès du jeune, derrière des branches basses.","Carnoc resta accroupi un instant. Ses doigts étaient sales et une éraflure courait sur le dos de sa main. Belenmar lui toucha l’épaule. Il se releva, ramassa ce qui était tombé sur le chemin et rejoignit les autres."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P14 — Version disponible","sourceLines":[97,99],"planOrigin":12,"plan":"Les liens des pièges servent à attacher les hommes ; ils sont cachés hors du passage.","staging":"Poids du corps déplacé et éraflure de Carnoc ; reprendre souffle."},{"id":"ep01-p15","number":15,"title":"Approcher Arloc","image":"images/P15-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["À mesure qu’ils approchaient d’Arloc, l’odeur de brûlé devenait plus forte. Ils abandonnèrent le chemin avant qu’il débouche au village et suivirent un talus. Une trouée leur montra un toit, puis un mur ; il fallut contourner un fourré et remonter un peu pour découvrir la rive.","Des hommes se déplaçaient entre les maisons. Plus loin, une barque chargée quittait le bord. Orvenn se pencha pour chercher son atelier, mais le talus lui en cachait la place.","Belenmar désigna le côté de la forge. Avec Carnoc, il pouvait l’approcher par les couverts qu’ils connaissaient. Maelrun montra aux deux frères un arbre en retrait où ils se retrouveraient, puis partit avec Orvenn dans l’autre direction."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P15 — Version disponible","sourceLines":[101,105],"planOrigin":13,"plan":"Approche d'Arloc par le talus ; première vue partielle du village ; séparation en deux binômes.","staging":"Montrer les obstacles à la vue et le point de rendez-vous."},{"id":"ep01-p16","number":16,"title":"L’atelier d’Orvenn","image":"images/P16-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Ils avancèrent courbés, s’arrêtant chaque fois qu’une voix se rapprochait. Le passage familier vers l’atelier était à découvert. Orvenn voulut gagner un peu de hauteur ; Maelrun le suivit derrière des buissons d’où ils aperçurent enfin une partie des bois renversés et l’ouverture de la porte. Quelqu’un avait tiré dehors un établi. Orvenn resta à le regarder."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P16 — Version disponible","sourceLines":[107,107],"planOrigin":14,"plan":"Maelrun et Orvenn découvrent l'atelier bouleversé.","staging":"Regard d'Orvenn fixé sur les objets familiers déplacés."},{"id":"ep01-p17","number":17,"title":"La forge","image":"images/P17-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["De leur côté, Belenmar et Carnoc avaient atteint la limite d’un petit couvert. La forge était ouverte. Des objets encombraient le sol devant elle et une pièce de bois brûlait encore contre le mur. Carnoc chercha leur père parmi les silhouettes qui passaient. Belenmar lui prit le poignet lorsqu’il avança trop près du bord."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P17 — Version disponible","sourceLines":[109,109],"planOrigin":15,"plan":"Les frères découvrent la forge et cherchent leur père ; Belenmar retient Carnoc.","staging":"Alternance entre le lieu connu et la recherche des personnes."},{"id":"ep01-p18","number":18,"title":"Les captifs","image":"images/P18-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Sur la rive, des habitants descendaient vers une embarcation. Ils marchaient serrés, gênés par leurs liens et par les hommes qui les pressaient. Un captif de haute taille se détourna pour laisser passer quelqu’un devant lui. Une de ses épaules restait plus basse ; tout son corps accompagnait ce côté quand il reprit sa marche.","— Le père d’Orvenn, murmura Belenmar.","Carnoc suivit son regard. Une femme plus petite avançait contre l’homme. Il crut reconnaître son manteau, puis un garde passa devant elle. Il se déplaça derrière les branches pour la retrouver. Le groupe descendait déjà vers la barque.","Ils cherchèrent encore leur propre père. Des captifs avaient pris place à bord ; d’autres étaient cachés par les hommes du rivage. Carnoc regardait chaque tête qui se relevait. Belenmar ne lâchait plus son poignet."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P18 — Version disponible","sourceLines":[111,117],"planOrigin":16,"plan":"Des captifs gagnent une barque ; Belenmar reconnaît le père d'Orvenn.","staging":"Reconnaissance par la silhouette ; garder l'incertitude sur la mère."},{"id":"ep01-p19","number":19,"title":"Le repli","image":"images/P19-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Près de l’atelier, Maelrun vit plusieurs pirates quitter les maisons et se diriger vers les chemins. Il tira doucement Orvenn en arrière. Le garçon résistait, les yeux sur sa porte, puis il remarqua les hommes qui approchaient et recula avec lui.","Ils retrouvèrent les frères sous l’arbre. Carnoc était couvert de feuilles sur un côté. Belenmar parla bas, en regardant Orvenn."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P19 — Version disponible","sourceLines":[119,121],"planOrigin":17,"plan":"Des pirates approchent des chemins ; les garçons se replient et se retrouvent.","staging":"Continuité des couverts et convergence des deux binômes."},{"id":"ep01-p20","number":20,"title":"L’annonce à Orvenn","image":"images/P20-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["— J’ai vu ton père. Ils le faisaient monter dans une barque.","Orvenn attendit la suite.","— Ta mère était peut-être avec lui. Je crois que c’était elle.","Le garçon se retourna vers le village. Il demanda de quel endroit ils les avaient vus, puis voulut passer entre eux. Maelrun lui barra doucement le passage du bras.","— Des hommes montent vers les chemins.","Orvenn repoussa son bras sans force. Il regarda encore la pente, la fumée au-dessus et les branches qui cachaient maintenant tout le reste."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P20 — Version disponible","sourceLines":[123,133],"planOrigin":18,"plan":"Belenmar annonce ce qu'il a vu ; Orvenn veut repartir ; Maelrun rappelle le danger.","staging":"Temps de réaction d'Orvenn et bras qui lui barre doucement le passage."},{"id":"ep01-p21","number":21,"title":"Prévenir Morna","image":"images/P21-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Carnoc demanda si leur père avait été aperçu près de l’atelier. Maelrun secoua la tête. Belenmar baissa les yeux, puis ramena Carnoc contre le tronc lorsqu’une voix leur parvint d’en bas.","Ils attendirent qu’elle s’éloigne. Maelrun pensait aux deux hommes attachés sur le chemin, à Elvenn qui marchait avec les enfants. Il regarda la direction de la clairière.","— Morna est avec les filles.","Belenmar releva la tête. Elles pouvaient revenir vers le village sans savoir. Ils quittèrent leur couvert et reprirent les bois, en s’écartant du chemin par lequel ils étaient descendus."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P21 — Version disponible","sourceLines":[135,141],"planOrigin":19,"plan":"Les frères interrogent Maelrun sur leur père ; le groupe pense à Morna et part la prévenir.","staging":"L'absence de réponse pèse avant le départ vers la clairière."},{"id":"ep01-p22","number":22,"title":"Dans la clairière","image":"images/P22-selection.jpg","hasImage":true,"status":"Composition validée","paragraphs":["Dans la clairière, Treva soulevait un écheveau pour vérifier que les fils séchaient jusqu’au cœur. Maona étalait des feuilles près de Morna, tandis qu’Enaëlle débarrassait un linge des tiges qu’elles avaient fini de trier. Leurs mains avaient gardé la couleur du travail.","Morna releva la tête au cri d’un corbeau. Deux autres quittèrent les branches en face d’elle et s’éloignèrent au-dessus de la clairière. Elle regarda sous les arbres, à l’endroit d’où ils venaient de s’envoler. Personne n’apparaissait et aucune voix ne les appelait. Ceux d’Arloc se seraient annoncés en approchant ; des étrangers avançaient sous le couvert.","Ils étaient trois à les avoir trouvées."],"notes":"Les cris et l’envol des corbeaux alertent Morna. Aucun pirate n’est visible depuis sa place dans la clairière ; elle déduit la présence d’étrangers de cette perturbation et de l’absence d’annonce. Les cases consacrées aux pirates renseignent le lecteur, pas Morna.","annotations":[{"case":"Clairière — perception","quote":"modifie le texte dans la liseuse la perception dans la clairière et la confirmation dans le chemin avant la poudre.","state":"Texte modifié le 27 septembre 2026","pending":false},{"case":"Case 5","quote":"la sorcière a les cheveux détachés et une natte à droite disparaît devant.\najoutes un croa croa ou l’onomatopée du cri du corbeau","state":"Intégré — version conservée","pending":false}],"history":[{"label":"P22 · 01 — Avant recomposition","filename":"P22-01-Avant-recomposition.png","image":"images/P22-01-ancienne.png"},{"label":"P22 · 02 — Recomposition — avant correction de la coiffure","filename":"P22-02.png","image":"images/P22-02-historique.png"}],"currentLabel":"P22 · 03 — Version sélectionnée","sourceLines":[167,171],"planOrigin":24,"plan":"Morna et les trois jeunes femmes travaillent. Les corbeaux réagissent dans les arbres ; Morna en déduit une présence étrangère sans apercevoir les hommes.","staging":"Respecter le point de vue de Morna : personne de visible depuis la clairière. Distinguer ce qu’elle perçoit de ce que les cases des pirates montrent au lecteur.","editorialRevision":"2026-09-27"},{"id":"ep01-p23","number":23,"title":"Nous rentrons","image":"images/P23-selection.jpg","hasImage":true,"status":"Case 6 à retoucher","paragraphs":["Ils avaient dû quitter le chemin, suivre les bruits et avancer entre les couverts pour découvrir ce qu’abritait la clairière. L’aîné retint le plus jeune par la manche lorsqu’il voulut se montrer. Il désigna les femmes, puis le passage vers le village. Le jeune repartit chercher les autres pendant que les deux hommes restaient à l’abri des arbres.","Morna posa son ouvrage dans un panier.","— Prenez les linges. Nous rentrons.","Treva regarda les écheveaux encore suspendus. Morna répéta son nom, doucement, et la jeune fille ramassa ce qu’elle avait à ses pieds. Elles s’engagèrent sur le passage de la chaumière. Morna fermait la marche."],"notes":"Case 6 : reboucher les silhouettes résiduelles au poste de travail. Ne conserver que les quatre femmes qui partent au fond de la clairière.","annotations":[{"case":"Case 6","quote":"Ok remplace p23 et notes à reboucher 6","state":"À reprendre","pending":true,"detail":"Reboucher les silhouettes résiduelles au poste de travail ; conserver les quatre femmes qui partent au fond de la clairière."}],"history":[{"label":"P23 · 01 — Avant recomposition","filename":"P23-01-Avant-recomposition.png","image":"images/P23-01-historique.png"},{"label":"P23 · 02 — Décor et lumière harmonisés","filename":"P23-02.png","image":"images/P23-02-historique.png"},{"label":"P23 · 03 — Panorama en case 6 — doublons présents","filename":"P23-03.png","image":"images/P23-03-historique.png"}],"currentLabel":"P23 · 04 — Version sélectionnée","sourceLines":[173,177],"planOrigin":25,"plan":"Le jeune pirate repart chercher du renfort ; Morna fait ranger et quitter la clairière.","staging":"Rendre la séparation des pirates compréhensible."},{"id":"ep01-p24","number":24,"title":"La poudre sur le chemin","image":"images/P24-selection.jpg","hasImage":true,"status":"Composition validée","paragraphs":["Au premier détour, Morna regarda derrière elle. Deux hommes avançaient entre les arbres, sur le passage qu’elles venaient de prendre. Ils les suivaient. Elle demanda aux filles de continuer et les laissa prendre de l’avance. Puis elle prit une petite réserve de poudre parmi ses affaires et en répandit un nuage sur le passage avant de les rejoindre.","Les hommes débouchèrent entre les branches. Le premier traversa l’endroit, porta une main à son visage et ralentit. Son compagnon le heurta presque. Ils firent encore quelques pas ; l’un chercha un appui contre un arbre, l’autre tomba sur les genoux. Morna vit leurs silhouettes s’affaisser, puis pressa les filles vers la chaumière."],"notes":"Morna confirme visuellement la poursuite avant de préparer la poudre. Le dessin précise ensuite le geste en la montrant souffler vers la végétation ; ce détail reste à harmoniser dans la prochaine révision.","annotations":[{"case":"Chemin — confirmation","quote":"modifie le texte dans la liseuse la perception dans la clairière et la confirmation dans le chemin avant la poudre.","state":"Texte modifié le 27 septembre 2026","pending":false},{"case":"Cases 2, 4 et 6","quote":"mets le bâton main droite en 2 et la main gauche dans le pochette.\n4 les femmes sont plus loin dans le chemin.\n6 les pirates sont allongés plus loin dans le chemin.\nle reste ok","state":"Intégré — version conservée","pending":false}],"history":[{"label":"P24 · 01 — Avant recomposition","filename":"P24-01-Avant-recomposition.png","image":"images/P24-01-ancienne.png"},{"label":"P24 · 02 — Recomposition — avant correction des mains et distances","filename":"P24-02.png","image":"images/P24-02-historique.png"}],"currentLabel":"P24 · 03 — Version sélectionnée","sourceLines":[179,181],"planOrigin":26,"plan":"Dans le chemin, Morna voit les deux hommes suivre le groupe. Cette confirmation la décide à laisser les filles avancer puis à répandre la poudre.","staging":"Sens du déplacement et emplacement du nuage ; aucun effet magique ajouté.","editorialRevision":"2026-09-27"},{"id":"ep01-p25","number":25,"title":"Emplacement à réattribuer","image":"images/P25-selection.jpg","hasImage":false,"status":"Raccord à décider","paragraphs":[],"notes":"Emplacement conservé pour ne pas renuméroter les planches produites. L’ancien découpage et le montage illustré divergent ici. Aucun événement ajouté et aucun texte dupliqué.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P25 — Version disponible","sourceLines":[],"planOrigin":null,"plan":"Réserver cette page jusqu’à validation du raccord entre la fuite des femmes et l’interception du messager.","staging":"Page volontairement blanche."},{"id":"ep01-p26","number":26,"title":"Emplacement à réattribuer","image":"images/P26-selection.jpg","hasImage":false,"status":"Raccord à décider","paragraphs":[],"notes":"Emplacement conservé pour ne pas renuméroter les planches produites. L’ancien découpage et le montage illustré divergent ici. Aucun événement ajouté et aucun texte dupliqué.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P26 — Version disponible","sourceLines":[],"planOrigin":null,"plan":"Réserver cette page jusqu’à validation du raccord entre la fuite des femmes et l’interception du messager.","staging":"Page volontairement blanche."},{"id":"ep01-p27","number":27,"title":"Le messager","image":"images/P27-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Sur un autre passage, les garçons entendirent courir avant de voir quelqu’un. Un jeune homme venait de la direction de la clairière. Belenmar s’arrêta derrière un tronc. Maelrun et Orvenn s’écartèrent, leurs frondes déjà en main.","Le messager les aperçut et voulut changer de direction. Carnoc lui coupa le passage ; il se retourna vers Belenmar, qui arrivait sur lui. Maelrun leva sa fronde. Le garçon hésita assez longtemps pour que les frères l’atteignent.","La lutte les entraîna contre les racines. Orvenn vint tenir un bras pendant qu’ils l’attachaient. Maelrun regardait le chemin de la clairière. Dès que le prisonnier fut bâillonné et tiré à l’écart, ils repartirent."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P27 — Version disponible","sourceLines":[183,187],"planOrigin":27,"plan":"Les garçons interceptent le messager, l'attachent et poursuivent vers la clairière.","staging":"Axes d'arrivée et issues coupées par les frères."},{"id":"ep01-p28","number":28,"title":"La clairière désertée","image":"images/P28-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Ils trouvèrent le lieu de travail désert. Les écheveaux pendaient encore entre les arbres et quelques feuilles étaient restées sur le linge. Carnoc appela Morna à mi-voix. Belenmar lui fit signe de se taire et regarda vers le passage de la chaumière.","Ils s’y engagèrent. Au-delà d’un détour, un homme était étendu près du chemin. Un autre reposait un peu plus loin. Maelrun ralentit pour les regarder ; Carnoc le dépassa en courant."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P28 — Version disponible","sourceLines":[189,191],"planOrigin":28,"plan":"Clairière vide, ouvrages laissés ; ils prennent le passage de la chaumière et voient les hommes au sol.","staging":"Recherche, indices puis progression dans le passage contaminé."},{"id":"ep01-p29","number":29,"title":"Atteindre la chaumière","image":"images/P29-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Une odeur lui prit la gorge. Maelrun passa la main devant son visage et suivit les autres. Le sol sembla bouger sous ses pieds. Il heurta Orvenn, se retint à lui, puis dut s’appuyer contre un arbre. Devant eux, Belenmar avançait de travers.","— Continue, souffla-t-il à Carnoc.","La chaumière restait cachée derrière les branches. Ils atteignirent enfin le bout du passage et virent la porte. Carnoc appela. Maelrun voulut le rejoindre plus vite, mais ses jambes cédèrent lorsqu’il franchit le seuil.","Morna se pencha aussitôt vers lui. Elle regarda les autres qui entraient, leurs visages, leurs mains tendues vers les murs, puis demanda une fiole à Enaëlle. Treva tira un siège pour Belenmar. Orvenn s’était assis par terre, le dos contre la paroi.","Morna fit respirer la fiole à Maelrun, puis passa auprès des autres. Il resta les yeux fermés, la main sur le sol. Son cœur battait trop vite et il avait du mal à reprendre son souffle. Quand il put regarder devant lui, Maona lui tendait de l’eau.","— Il y avait deux hommes sur le chemin, dit-il.","— Je sais, répondit Morna. Reste assis.","Carnoc avait appuyé les coudes sur ses genoux. Belenmar lui demanda s’il pouvait respirer. Il acquiesça, puis recommença à tousser. Pendant un moment, on entendit surtout les garçons reprendre leur souffle et les pas des filles autour d’eux."],"notes":"La planche disponible montre les soins dehors, tandis que le récit les situe à l’intérieur de la chaumière : décor à harmoniser.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P29 — Version disponible","sourceLines":[193,207],"planOrigin":29,"plan":"Les garçons subissent la poudre ; ils atteignent la porte et Maelrun s'effondre au seuil.","staging":"Dégradation des appuis ; chaumière révélée seulement au bout du passage."},{"id":"ep01-p30","number":30,"title":"Le récit des garçons","image":"images/P30-selection.jpg","hasImage":true,"status":"Version disponible","paragraphs":["Orvenn parla le premier du village. Les mots venaient lentement. Il dit le feu, l’atelier ouvert, les hommes qui fouillaient les maisons. Maelrun ajouta les barques et les captifs conduits à la rive. Treva avait gardé dans la main le linge qu’elle venait de mouiller.","— Ils les emmènent ? demanda Enaëlle.","Belenmar hocha la tête. Il regarda Orvenn avant de parler de son père. Le garçon fixait le sol entre ses pieds.","Morna voulut savoir où étaient les enfants. Maelrun lui expliqua qu’Elvenn les avait éloignés du chemin. Ils l’avaient quitté dans les bois, avant de rencontrer les deux premiers hommes. Il raconta ceux qu’ils avaient attachés, puis le messager intercepté en venant.","Des sabots se firent entendre dehors. Treva se tourna vers la porte, mais Morna avait déjà levé la main pour qu’elle attende. Le bruit ralentit, puis une voix les appela."],"notes":"La planche disponible rassemble une partie des soins, le récit et les sabots. Le texte est réparti ici selon ces actions ; sa mise en scène extérieure diffère encore du récit.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P30 — Version disponible","sourceLines":[209,217],"planOrigin":30,"plan":"Morna soigne ; les filles apportent siège, fiole et eau ; les garçons reprennent souffle.","staging":"Répartition des corps dans une pièce à cadrer avant dessin."},{"id":"ep01-p31","number":31,"title":"L’arrivée d’Arua","image":"images/P31-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Arua entra en tenant encore ses rênes. Elle regarda les garçons assis contre les murs, s’arrêta devant Carnoc et se baissa vers lui. Il lui montra Morna d’un mouvement de tête.","— Ça passe."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P31 — Version disponible","sourceLines":[219,221],"planOrigin":31,"plan":"Les sabots ralentissent ; Arua entre et se baisse auprès de Carnoc.","staging":"Dialogues à fixer depuis les passages en discours indirect."},{"id":"ep01-p32","number":32,"title":"Arua auprès de Carnoc","image":"images/P32-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Elle lui prit brièvement la main, vit l’éraflure et le laissa auprès de son frère. Maelrun s’était redressé. Arua demanda qui avait vu le village, puis écouta leurs réponses. Lorsqu’ils eurent fini, elle raconta la barque, les hommes sur l’estran et le chemin qu’elle avait repris pour les rejoindre."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P32 — Version disponible","sourceLines":[223,223],"planOrigin":32,"plan":"Arua remarque l’éraflure, prend brièvement la main de Carnoc et écoute les garçons ; elle raconte ensuite sa rencontre.","staging":"Retrouvailles et attention familière d'Arua."},{"id":"ep01-p33","number":33,"title":"Préparer le départ","image":"images/P33-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Maona posa un récipient près d’elle. Arua but, puis revint vers la porte pour desserrer ce qui retenait son cheval. Dehors, il cherchait l’herbe au bord du seuil. Elle resta près de son encolure un instant avant de rentrer.","À l’intérieur, Morna avait demandé aux filles de réunir ce qu’elles pourraient porter. Enaëlle sortait les linges d’un panier pour y placer des provisions. Belenmar voulut l’aider ; en se levant, il dut poser la main contre le mur. Carnoc le regarda et lui fit de la place à côté de lui.","Morna noua le linge autour de ce qu’Enaëlle avait réuni. Elle demanda aux garçons de lui montrer d’où venait le messager. Maelrun se leva avec précaution et alla jusqu’à la porte. Le passage disparaissait derrière les arbres, mais ils savaient maintenant que des hommes l’avaient suivi depuis le village."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P33 — Version disponible","sourceLines":[225,229],"planOrigin":33,"plan":"Arua rapporte sa rencontre ; les provisions se rassemblent ; le danger des chemins est évalué.","staging":"Éviter une répétition illustrée de l'affrontement déjà montré."},{"id":"ep01-p34","number":34,"title":"La séparation","image":"images/P34-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["— Il faut rejoindre Elvenn, dit Morna.","Orvenn leva la tête. Il pouvait les ramener à l’endroit où ils avaient quitté les enfants. Au-delà, il faudrait chercher. Arua regarda les paniers, les filles qui attendaient et les garçons encore assis.","— Allez avec lui. Nous retournerons voir près du village.","Elle montra Maelrun et les deux frères. Belenmar se leva lentement, attendit que ses jambes le portent, puis prit le panier que Treva achevait de remplir. Il le déposa près de la porte pour Orvenn. Carnoc resta un moment devant les outils et les affaires qu’ils laisseraient. Morna lui passa un paquet à tenir pendant qu’elle resserrait sa courroie.","Ils sortirent ensemble. À la séparation des chemins, Orvenn se retourna vers Belenmar. Il ouvrit la bouche, puis regarda les trois garçons l’un après l’autre.","— Si vous les voyez encore…","Belenmar acquiesça. Orvenn suivit Morna. Ils marchèrent d’abord assez près pour entendre Arua parler à son cheval, puis leurs pas les entraînèrent derrière le relief et les voix cessèrent de leur parvenir."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P34 — Version disponible","sourceLines":[231,243],"planOrigin":34,"plan":"Décision de rejoindre Elvenn ; répartition ; demande inachevée d'Orvenn à la séparation.","staging":"Le groupe se divise matériellement et affectivement."},{"id":"ep01-p35","number":35,"title":"Retrouver les enfants","image":"images/P35-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Le bois paraissait vide à l’endroit où les enfants s’étaient tenus. Orvenn reconnut le passage, puis l’arbre près duquel Elvenn avait montré la fumée. Il chercha des yeux de quel côté ils avaient pu partir. Plusieurs ouvertures s’offraient entre les troncs. Morna lui demanda ce que le druide avait dit en les quittant.","Il se rappelait seulement qu’il voulait éloigner les enfants du chemin. Ils contournèrent le lieu de leur rencontre et avancèrent vers l’intérieur, en prenant le temps d’écouter. Treva s’arrêta derrière eux, le panier contre la hanche. Un oiseau remuait dans les branches ; plus loin, une tige craqua, puis tout redevint silencieux.","Ils cherchèrent encore. Orvenn s’engagea dans un passage qui se referma entre les ronces et revint auprès des femmes. Morna lui indiqua une pente plus douce. Elvenn devait tenir compte des petites jambes et des endroits où les enfants pourraient se dissimuler."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P35 — Version disponible","sourceLines":[247,251],"planOrigin":35,"plan":"Orvenn, Morna et les filles cherchent les traces du groupe d'enfants ; un passage se ferme.","staging":"La recherche prend du temps et impose un détour."},{"id":"ep01-p36","number":36,"title":"Le couvert d’Elvenn","image":"images/P36-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Ils avaient quitté depuis un moment les abords de la chaumière lorsqu’une voix basse prononça le nom de Morna. Brieg se tenait à demi caché derrière un tronc. Il leur fit signe de rester où ils étaient, se retourna et disparut un instant. Elvenn vint à sa place.","Orvenn se sentit soudain trop chargé. Il posa le panier et voulut parler, mais Morna le devança. Elle raconta le départ précipité de la clairière et montra les filles. Elvenn les fit passer dans le couvert avant d’écouter le reste.","Les enfants étaient installés dans un creux où les branches basses coupaient la vue. Tara et Maëlis s’étaient serrées l’une contre l’autre. Ronan avait de la terre sur le visage ; Elen dormait à demi contre Brieg, qui reprit sa place dès qu’ils furent entrés. Loen regardait entre les feuilles dans la direction des visiteurs.","Morna posa sa main sur chaque tête en passant. Treva dégagea un peu de place pour les paniers. Enaëlle s’accroupit près d’Elen et lui souleva doucement les pieds pour qu’ils reposent sur un linge."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P36 — Version disponible","sourceLines":[253,259],"planOrigin":36,"plan":"Brieg les repère ; Elvenn vient les chercher ; accueil auprès des enfants cachés.","staging":"Détection avant découverte du refuge provisoire."},{"id":"ep01-p37","number":37,"title":"Orvenn et Maona","image":"images/P37-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Orvenn entraîna Elvenn à quelques pas. Il parla des maisons en feu, des prisonniers, de son père que Belenmar avait reconnu. Il raconta aussi les hommes sur les chemins et ceux qui avaient suivi Morna. Elvenn écoutait en regardant de temps à autre vers les enfants.","— Arua est retournée voir avec les autres, acheva Orvenn.","Le druide lui montra, entre les troncs, la direction d’Arloc ancien. Le village était proche, mais les enfants resteraient ici tant qu’ils ignoreraient si les pirates pouvaient encore les chercher. Il avait trouvé de quoi les cacher et surveillait le passage par lequel d’autres survivants pourraient arriver.","Orvenn s’assit au pied d’un arbre, à l’écart du groupe. Maona vint lui apporter de l’eau. Il but un peu, puis conserva le récipient entre ses mains.","— Ils ont vu ton père ? demanda-t-elle.","Il hocha la tête. Elle s’assit près de lui. Pendant un moment, ils regardèrent les feuilles remuer au-dessus du passage. Puis Maona reprit le récipient et retourna vers les enfants."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P37 — Version disponible","sourceLines":[261,271],"planOrigin":37,"plan":"Orvenn fait son rapport ; Elvenn maintient les enfants à couvert ; Maona s'assied près d'Orvenn.","staging":"Donner une place au silence partagé."},{"id":"ep01-p38","number":38,"title":"Retour vers Arloc","image":"images/P38-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Arua mit pied à terre avant de retrouver les approches d’Arloc. Sous le couvert, elle conduisit le cheval par la bride. Maelrun passait devant aux endroits qu’il connaissait ; les deux frères vérifiaient le chemin derrière eux. Ils avançaient plus lentement que le matin et s’arrêtaient aux ouvertures pour observer avant de franchir un espace découvert.","Ils retrouvèrent un angle sur le village. La fumée avait changé de forme. Certaines maisons brûlaient encore ; ailleurs, il restait des murs noircis et des charpentes abattues. Des hommes transportaient des charges vers les barques. Une voix criait depuis le rivage, suivie du bruit d’un objet qu’on laissait tomber.","Orvenn leur avait demandé de regarder. Belenmar parcourut les groupes visibles, chercha la haute silhouette près des embarcations et attendit qu’un homme se déplace pour voir derrière lui. Les prisonniers qu’ils avaient observés le matin avaient déjà quitté la rive.","Carnoc se pencha vers la forge. Il pouvait en voir un peu plus de ce côté. Il fixa l’ouverture sombre, puis le tas d’objets devant le mur. Maelrun changea de place pour regarder les maisons voisines. Ils espéraient encore qu’une personne cachée paraîtrait à une porte, qu’un mouvement familier se détacherait des autres."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P38 — Version disponible","sourceLines":[275,281],"planOrigin":38,"plan":"Arua, Maelrun et les frères reviennent observer Arloc ; les captifs vus le matin ont disparu de la rive.","staging":"Cheval conduit à la main ; recherche depuis un couvert."},{"id":"ep01-p39","number":39,"title":"Attendre et repartir","image":"images/P39-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Ils attendirent. Arua s’était accroupie près d’eux. De temps en temps, elle se retournait vers le cheval et lui posait la main sur le chanfrein lorsqu’il cherchait à avancer. Sur la rive, les allées et venues se poursuivaient. Le temps passait dans les mêmes bruits d’eau, d’appels et de charges déplacées.","Lorsque les dernières barques eurent quitté le bord, quelques hommes restèrent encore à proximité des maisons. Arua les suivit du regard, puis fit signe aux garçons de reculer avec elle. Elle demanda aux deux frères de rejoindre Elvenn et de prévenir le groupe que les navires étaient toujours dans la baie. Maelrun resterait avec elle jusqu’à leur départ.","Belenmar regarda Carnoc. Celui-ci ne bougeait pas. Il fixait encore l’endroit où la forge disparaissait derrière les branches.","— Viens, lui dit son frère."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P39 — Version disponible","sourceLines":[283,289],"planOrigin":39,"plan":"Attente pendant le chargement ; Arua renvoie les frères ; Carnoc tarde à quitter la forge des yeux.","staging":"Usure de l'attente et dernier regard."},{"id":"ep01-p40","number":40,"title":"Le départ des navires","image":"images/P40-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Ils quittèrent le couvert ensemble. Arua et Maelrun reprirent leur place, assez en retrait pour rester cachés. Sur l’eau, une embarcation allait d’un navire à l’autre. Plus tard, il fallut encore attendre que des hommes gagnent le bord et que les voiles soient disposées.","Maelrun avait les jambes engourdies. Il les allongea avec précaution et chercha dans ses affaires quelque chose à manger. Il en tendit une part à Arua. Elle la prit sans quitter longtemps la baie des yeux.","Un navire commença enfin à se déplacer. Ils regardèrent sa position changer par rapport à la côte, puis l’espace grandir derrière lui. Le mouvement se poursuivit vers la sortie. Arua se redressa pour suivre les voiles jusqu’à ce que la rive les masque. Elle attendit encore, puis regarda Maelrun."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P40 — Version disponible","sourceLines":[291,295],"planOrigin":40,"plan":"Arua et Maelrun restent ; partage de nourriture ; mise en mouvement et départ des navires.","staging":"Plusieurs états successifs de la baie rendent le temps sensible."},{"id":"ep01-p41","number":41,"title":"Chercher dans les ruines","image":"images/P41-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Ils descendirent par le bord du village. Arua gardait le cheval à la main. Maelrun appela doucement depuis une première porte et écouta. Un morceau de bois tomba à l’intérieur. Il recula, contourna le mur et regarda dans la cour voisine.","Ils passèrent ainsi d’un endroit à l’autre, s’arrêtant pour entendre ce qui venait des maisons. Auprès de l’atelier, Maelrun reconnut un outil dans la terre. Il le ramassa, en essuya le manche contre sa tunique et le glissa à sa ceinture. Arua l’appela depuis le passage. Le toit au-dessus de lui craquait encore.","Ils cherchèrent dans les abords qu’ils pouvaient atteindre, derrière les murs restés debout et près des sorties vers les bois. Leurs appels demeurèrent sans réponse. Maelrun regardait chaque recoin avant de rejoindre Arua. Elle lui laissa le temps de vérifier une dernière ouverture, puis ils reprirent la route des enfants."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P41 — Version disponible","sourceLines":[297,301],"planOrigin":41,"plan":"Après le départ, ils cherchent dans Arloc ; Maelrun retrouve un outil ; aucun appel ne reçoit de réponse.","staging":"Parcours prudent des ruines ; ne pas dessiner de victime absente du texte."},{"id":"ep01-p42","number":42,"title":"Les enfants attendent","image":"images/P42-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Belenmar et Carnoc avaient trouvé le groupe après avoir appelé bas et attendu qu’Orvenn se montre. Ils étaient restés près de lui pour expliquer d’où arriveraient Arua et Maelrun, puis s’étaient répartis avec les jeunes femmes autour du couvert. De là, ils pouvaient voir quelqu’un approcher avant qu’il découvre les enfants.","Ronan avait demandé plusieurs fois quand ils rentreraient. Morna lui répondait qu’ils attendaient les autres. À chaque bruit, il levait les yeux vers elle. Elen s’était réveillée en pleurant ; Enaëlle l’avait prise contre elle et marchait doucement entre deux arbres.","L’après-midi avançait. Loen voulut aller jusqu’à l’endroit d’où l’on pouvait apercevoir les toits du village ancien. Brieg le retint par sa tunique. Le petit protesta, puis se mit lui aussi à pleurer, de colère d’abord, avant de se serrer contre le garçon. Brieg regarda Elvenn. Le druide vint s’asseoir près d’eux et posa son bâton au sol."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P42 — Version disponible","sourceLines":[305,309],"planOrigin":42,"plan":"Les frères organisent la surveillance du couvert ; les enfants attendent, questionnent et pleurent.","staging":"Positions des guetteurs et gestes de réconfort."},{"id":"ep01-p43","number":43,"title":"L’outil retrouvé","image":"images/P43-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Quand le bruit du cheval leur parvint, Belenmar fit signe à Carnoc de rester caché. Ils attendirent que les branches laissent voir les arrivants. Maelrun marchait devant Arua. Il regardait autour de lui, cherchant l’endroit où les autres avaient pu s’arrêter.","Belenmar se montra et leva la main. Maelrun s’immobilisa, le reconnut, puis vint vers lui. Arua les rejoignit en conduisant le cheval. Ils descendirent derrière les arbres et trouvèrent enfin les enfants, les paniers et les visages tournés vers eux.","— Les navires sont partis, dit Arua à Elvenn.","Elle précisa qu’ils les avaient regardés quitter la baie avant d’approcher les maisons. Maelrun raconta leur recherche. Il sortit l’outil de sa ceinture et le tendit à Orvenn. Le garçon le retourna dans ses mains, frotta du pouce une marque sur le bois et demanda où il l’avait trouvé.","Autour d’eux, personne ne se levait encore. Morna regarda Arua, qui secoua lentement la tête. Ils n’avaient trouvé personne à ramener."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P43 — Version disponible","sourceLines":[311,319],"planOrigin":43,"plan":"Arua et Maelrun sont repérés puis accueillis ; départ confirmé ; l'outil revient à Orvenn.","staging":"Faire durer le geste de reconnaissance de l'outil."},{"id":"ep01-p44","number":44,"title":"Vers Arloc ancien","image":"images/P44-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Elvenn demanda qu’on réunisse les affaires. Ils pouvaient maintenant gagner Arloc ancien. Les enfants se mirent debout avec raideur. Treva ramassa un linge, le secoua et le replia pendant que Maona aidait Ronan à remettre ce qu’il avait défait à ses pieds.","Le groupe sortit du couvert par petites files. Elvenn connaissait les accès ; il choisit un passage assez large pour ceux qui portaient les paniers. Arua conduisait son cheval. Brieg tenait Elen par la main jusqu’à ce qu’elle refuse d’avancer ; Belenmar la souleva et la cala contre lui. Elle posa aussitôt la tête sur son épaule.","Ils marchèrent encore avant d’atteindre les premières constructions. Le village ancien apparaissait par morceaux, un mur derrière les feuilles, une pente de toit, puis un passage resserré entre deux bâtiments. Elvenn s’arrêta pour écouter et fit signe aux autres d’attendre pendant qu’il avançait avec Arua.","Le lieu était resté intact. Les portes, les chemins et les abords ne portaient aucune trace du passage des pirates. Ils vérifièrent l’accès qu’ils venaient de prendre, puis une autre sortie. Quand Elvenn revint chercher les enfants, Morna reprit son panier et le groupe entra."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P44 — Version disponible","sourceLines":[321,327],"planOrigin":44,"plan":"Le groupe quitte le couvert, marche jusqu'à Arloc ancien ; Elvenn et Arua vérifient les accès.","staging":"Distance parcourue ; les enfants attendent avant d'entrer."},{"id":"ep01-p45","number":45,"title":"Installer le refuge","image":"images/P45-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Ils choisirent un bâtiment où le sol demeurait sec. La lumière du dehors atteignait une partie de la pièce ; plus loin, il fallait attendre pour distinguer les murs. Les enfants s’assirent là où on les plaça. Orvenn déposa l’outil retrouvé contre la paroi et alla aider à dégager le sol.","Il manquait de quoi couvrir tout le monde. Maelrun regarda les manteaux étendus, puis les petits qui se serraient déjà dessus. Il parla bas à Belenmar et Carnoc. Ils pouvaient retourner chercher quelques affaires épargnées à Arloc pendant qu’il restait de la lumière.","Elvenn les écouta. Il leur demanda de rester ensemble et de revenir avant que l’obscurité les oblige à chercher leur chemin. Arua les accompagna jusqu’à la sortie du refuge, puis demeura là à les regarder partir."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P45 — Version disponible","sourceLines":[329,333],"planOrigin":45,"plan":"Installation dans un bâtiment sec ; manque de couvertures ; les trois garçons repartent chercher des ressources.","staging":"Organisation du refuge et sortie du petit groupe."},{"id":"ep01-p46","number":46,"title":"Les absents","image":"images/P46-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Pendant leur absence, les autres réunirent ce qu’ils avaient apporté. Morna partagea les provisions. Certains enfants prirent leur part et commencèrent à manger ; Tara la garda dans sa main. Elle demanda où était sa mère. Morna s’assit près d’elle et l’attira contre son épaule.","— Nous ne l’avons pas retrouvée.","Tara regarda vers l’entrée. Elle resta ainsi un moment, puis demanda si elle saurait où venir. Morna lui écarta les cheveux du visage. À côté d’elles, Maëlis avait cessé de mâcher.","Orvenn sortit. Il passa près d’Arua, qui se tenait auprès du cheval, et alla s’asseoir contre le mur. De l’intérieur venaient des questions auxquelles les adultes répondaient à voix basse. Arua desserra les sangles, arrangea ce qui reposait sur le dos de sa monture, puis vint s’accroupir près du garçon. Il tenait encore dans sa paume une petite saleté noire arrachée au manche de l’outil."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P46 — Version disponible","sourceLines":[335,341],"planOrigin":46,"plan":"Provisions partagées ; Tara demande sa mère ; Orvenn sort, Arua le rejoint près du mur.","staging":"Deux moments de deuil, intérieur puis extérieur."},{"id":"ep01-p47","number":47,"title":"Couvertures et bilan","image":"images/P47-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["Les trois autres revinrent avec des couvertures et quelques ressources récupérées. Il leur avait fallu refaire le chemin, chercher dans les endroits accessibles et porter leurs charges jusqu’au refuge. Carnoc déposa la sienne près de la porte. Belenmar resta courbé un instant, les mains sur les cuisses, avant de rejoindre Morna.","Maelrun apporta une couverture aux deux filles. Tara la tira aussitôt sur ses jambes. Il attendit qu’elle ait dégagé sa main, puis en rabattit le bord sur Maëlis. Plus loin, Enaëlle aidait Brieg à installer Elen pour qu’elle puisse dormir.","Ils gardèrent le feu éteint. La nourriture passa entre les groupes assis ; les voix baissèrent avec la lumière. Elvenn fit reprendre les noms des personnes aperçues sur la rive et de celles qu’on avait cherchées dans les maisons. Certaines avaient été vues montant dans les barques. Pour les autres, chacun disait seulement le dernier endroit où il les avait rencontrées.","Carnoc parla de leur père. Belenmar écoutait, un morceau de nourriture posé sur son genou. Quand son frère eut fini, il ajouta qu’ils n’avaient pu voir tous les captifs. Orvenn releva la tête, puis la baissa de nouveau."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P47 — Version disponible","sourceLines":[343,349],"planOrigin":47,"plan":"Retour chargé ; couvertures distribuées ; repas sans feu et bilan des personnes vues ou disparues.","staging":"Éviter de conclure au sort des absents."},{"id":"ep01-p48","number":48,"title":"La première garde","image":"images/P48-selection.jpg","hasImage":false,"status":"À illustrer","paragraphs":["À la nuit, les deux frères prirent place près de l’un des accès. Elvenn leur avait montré d’où prévenir le groupe et par où rentrer si plusieurs hommes approchaient. Ils restèrent sous le couvert du mur, assez proches pour se parler sans hausser la voix.","Carnoc bougeait souvent les doigts de sa main éraflée. Belenmar finit par lui demander de la montrer. Il déchira une bande dans un linge abîmé, la passa autour de la main et chercha dans l’obscurité comment en rabattre le bout. Carnoc la lui laissa jusqu’à ce qu’il ait terminé."],"notes":"Rapprochement de travail avec le récit ; le texte source est conservé.","annotations":[{"case":"Suivi","state":"Repère éditorial","quote":"Aucune annotation récente rattachée à cette page dans cette édition.","pending":false}],"history":[],"currentLabel":"P48 — Version disponible","sourceLines":[351,353],"planOrigin":48,"plan":"Première garde","staging":"Extérieur nocturne sobre, présence assourdie du refuge."}];
